func PhaseFromString(s string) Phase {
	switch Phase(s) {
	case PhaseActive:
		return PhaseActive
	case PhaseIdle:
		return PhaseIdle
	case PhaseEnded:
		return PhaseEnded
	case "active_committed":
		// Backward compat: old state files may have this value.
		return PhaseActive
	default:
		return PhaseIdle
	}
}

